// src/server/services/mfaService.ts
var JWT_SECRET = process.env.JWT_SECRET || "supersecretjwtstring";
var CHALLENGE_TTL_MS = 5 * 60 * 1e3;
var RESEND_COOLDOWN_MS = 60 * 1e3;
var TOTP_ISSUER = process.env.MFA_TOTP_ISSUER || "SPS Studio";
async function getFactorStatus(userId, accountContext) {
  const factors = await db.execute({ sql: "SELECT factor_type, is_enabled, is_primary FROM auth_factors WHERE user_id = ? AND account_context = ?", args: [userId, accountContext] });
  const recovery = await db.execute({ sql: "SELECT COUNT(*) AS count FROM auth_recovery_codes WHERE user_id = ? AND account_context = ? AND used_at IS NULL", args: [userId, accountContext] });
  const preference = await db.execute({ sql: "SELECT login_mode FROM auth_mfa_preferences WHERE user_id = ? AND account_context = ? LIMIT 1", args: [userId, accountContext] });
  const byType = new Map(factors.rows.map((row) => [String(row.factor_type), row]));
  const emailEnabled = Number(byType.get("email_otp")?.is_enabled || 0) === 1;
  const totpEnabled = Number(byType.get("totp")?.is_enabled || 0) === 1;
  const storedMode = String(preference.rows[0]?.login_mode || "");
  const loginMode = storedMode === "combined" && emailEnabled && totpEnabled ? "combined" : storedMode === "email_only" && emailEnabled ? "email_only" : storedMode === "totp_only" && totpEnabled ? "totp_only" : totpEnabled ? "totp_only" : emailEnabled ? "email_only" : null;
  return {
    email_otp_enabled: emailEnabled,
    totp_enabled: totpEnabled,
    login_mode: loginMode,
    primary_method: factors.rows.find((row) => Number(row.is_enabled) === 1 && Number(row.is_primary) === 1)?.factor_type || null,
    recovery_codes_remaining: Number(recovery.rows[0]?.count || 0)
  };
}
async function setMfaLoginMode(userId, accountContext, loginMode) {
  const status = await getFactorStatus(userId, accountContext);
  if ((loginMode === "email_only" || loginMode === "combined") && !status.email_otp_enabled) throw Object.assign(new Error("Enable email verification before selecting this mode."), { status: 409 });
  if ((loginMode === "totp_only" || loginMode === "combined") && !status.totp_enabled) throw Object.assign(new Error("Enable an authenticator before selecting this mode."), { status: 409 });
  await db.execute({ sql: `INSERT INTO auth_mfa_preferences (user_id, account_context, login_mode, updated_at) VALUES (?, ?, ?, CURRENT_TIMESTAMP) ON CONFLICT(user_id, account_context) DO UPDATE SET login_mode = excluded.login_mode, updated_at = CURRENT_TIMESTAMP`, args: [userId, accountContext, loginMode] });
}

// scripts/temp-test-mfa-modes.ts
async function main() {
  const userId = `mfa-mode-test-${Date.now()}`;
  const context = "admin";
  await setupDatabase();
  try {
    await db.batch([
      { sql: "INSERT INTO auth_factors (id, user_id, account_context, factor_type, is_enabled, is_primary) VALUES (?, ?, ?, 'email_otp', 1, 0)", args: [import_node_crypto2.default.randomUUID(), userId, context] },
      { sql: "INSERT INTO auth_factors (id, user_id, account_context, factor_type, is_enabled, is_primary, secret_encrypted) VALUES (?, ?, ?, 'totp', 1, 1, 'test-only')", args: [import_node_crypto2.default.randomUUID(), userId, context] }
    ], "write");
    for (const mode of ["email_only", "totp_only", "combined"]) {
      await setMfaLoginMode(userId, context, mode);
      const status = await getFactorStatus(userId, context);
      if (status.login_mode !== mode) throw new Error(`Mode persistence failed: ${mode}`);
    }
    await db.execute({ sql: "UPDATE auth_factors SET is_enabled = 0 WHERE user_id = ? AND account_context = ? AND factor_type = 'email_otp'", args: [userId, context] });
    const fallback = await getFactorStatus(userId, context);
    if (fallback.login_mode !== "totp_only") throw new Error("Unsafe combined-mode fallback");
    console.log(JSON.stringify({ modes: ["email_only", "totp_only", "combined"], persistence: true, safeFallback: fallback.login_mode }));
  } finally {
    await db.execute({ sql: "DELETE FROM auth_mfa_preferences WHERE user_id = ?", args: [userId] });
    await db.execute({ sql: "DELETE FROM auth_factors WHERE user_id = ?", args: [userId] });
  }
}
main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
